quiz:[
  {"q":"לפי ההגדרה שהוצגה בשיעור, מהי \"אבטחת מידע\"?","options":["הגנה על מערכות ורשתות מפני התקפות דרך מרחב הסייבר","ניהול הרשאות המשתמשים לפי תפקידם בארגון","תיעוד פעולות המשתמשים לצורך חקירה בדיעבד","הגנה על מידע מפני חשיפה, שינוי ומחיקה"],"correct":3,"explain":"אבטחת מידע = הגנה על מידע מפני חשיפה, שינוי ומחיקה. הגנה על מערכות ורשתות מפני התקפות דרך מרחב הסייבר היא ההגדרה של אבטחת סייבר – תת-תחום של אבטחת מידע.","kind":"concept","difficulty":1,"slide":"14"},
  {"q":"לפי ההגדרה בשיעור, מה היחס בין אבטחת סייבר (Cybersecurity) לבין אבטחת מידע?","options":["אבטחת סייבר היא תת-תחום של אבטחת מידע","אבטחת מידע היא תת-תחום של אבטחת סייבר","אלה שני תחומים נפרדים ללא חפיפה ביניהם","אלה שני שמות נרדפים לאותו תחום בדיוק"],"correct":0,"explain":"המרצה מגדירה את אבטחת הסייבר כתת-תחום של אבטחת מידע, המתמקד ספציפית בהגנה על מערכות מחשב, רשתות ותשתיות דיגיטליות מפני התקפות דרך מרחב הסייבר. הכיוון ההפוך הוא המלכודת.","kind":"concept","difficulty":2,"slide":"14"},
  {"q":"בית חולים נועל בארון ממוגן את תיקי המטופלים המודפסים, כדי שלא ייחשפו, ישונו או יימחקו. לפי ההגדרות בשיעור, לאיזה תחום שייכת פעולה זו?","options":["אבטחת מידע – אך לא אבטחת סייבר, כי ההגנה אינה דרך מרחב הסייבר","אבטחת סייבר – כי כל הגנה על מידע רפואי נחשבת סייבר","אבטחת סייבר בלבד – כי אבטחת מידע עוסקת רק במחשבים","אבטחה פיזית בלבד, שאינה קשורה כלל לאבטחת מידע"],"correct":0,"explain":"אבטחת מידע = הגנה על מידע מפני חשיפה, שינוי, מחיקה – בכל צורה שבה הוא נשמר, גם על נייר. אבטחת סייבר היא תת-תחום שמתמקד בהגנה על מערכות מחשב, רשתות ותשתיות דיגיטליות מפני התקפות דרך מרחב הסייבר. ארון נעול מגן על מידע, אבל לא במרחב הסייבר – לכן זו אבטחת מידע ולא סייבר.","kind":"scenario","difficulty":2,"slide":"14"},
  {"q":"לפי מטרות הקורס, ממה מורכבת \"זירת ההתקפה\" שהקורס מנתח?","options":["סודיות, שלמות וזמינות","פשיעה, טרור ולוחמה דיגיטלית","פישינג, מתקפות DDoS ו-Deepfake","אנשים, תהליכים וטכנולוגיה"],"correct":1,"explain":"מטרת הקורס: לנתח את האיומים בסביבת המידע ואת זירת ההתקפה – פשיעה, טרור ולוחמה דיגיטלית. סודיות-שלמות-זמינות הם יעדי CIA, ואנשים-תהליכים-טכנולוגיה הם משולש הקסם.","kind":"concept","difficulty":1,"slide":"3"},
  {"q":"מהי Orion – המוצר המרכזי של SolarWinds שדרכו בוצעה המתקפה?","options":["תוכנת אנטי-וירוס לתחנות הקצה בארגון","שירות ענן לגיבויים ולתוכנית DRP","מערכת בקרה וניטור ארגונית לניהול הרשת","מערכת לניהול זהויות והרשאות (IAM)"],"correct":2,"explain":"SolarWinds מפתחת תוכנה לניטור וניהול רשת, בעיקר Orion – מערכת בקרה וניטור ארגונית. דווקא משום שמערכת כזו מותקנת עמוק ברשתות של ארגונים רבים, הפגיעה בה נתנה לתוקפים גישה רחבה.","kind":"case","difficulty":1,"slide":"17"},
  {"q":"כיצד השיגו התוקפים אחיזה ברשתות הלקוחות במתקפת SolarWinds?","options":["באמצעות קוד זדוני (SUNBURST) שהוחדר לעדכון רשמי של Orion","באמצעות מיילי פישינג שנשלחו ישירות לעובדי ארגוני הלקוחות","באמצעות מתקפת DDoS שהשביתה את חומות האש בארגוני הלקוחות","באמצעות עובד ממורמר ב-SolarWinds שהדליף סיסמאות של לקוחות"],"correct":0,"explain":"סביבת ה-build של Orion נפרצה, והוכנס קוד זדוני בשם SUNBURST לעדכון שהופץ ללקוחות. הלקוחות התקינו עדכון \"לגיטימי\" והקוד אוקטב אצלם – בלי פישינג, DDoS או איום פנימי.","kind":"case","difficulty":2,"slide":"17"},
  {"q":"במקרה SolarWinds, מה היה SUNBURST?","options":["מערכת הבקרה והניטור הארגונית ש-SolarWinds מפתחת","השרשרת שמייצרת את קוד העדכונים של Orion","קבוצת התוקפים שעמדה מאחורי המתקפה","הקוד הזדוני שהוכנס לעדכון שהופץ ללקוחות"],"correct":3,"explain":"SUNBURST הוא הקוד הזדוני שהוכנס לעדכון של Orion והופץ ללקוחות; הוא אוקטב אצלם ואפשר לתוקפים אחיזה ברשתות. אל תתבלבלו: Orion היא מערכת הבקרה והניטור (המוצר), ה-build environment היא השרשרת שמייצרת את קוד העדכונים (מה שנפרץ), ושם קבוצת התוקפים לא הוצג בשיעור.","kind":"case","difficulty":2,"slide":"17"},
  {"q":"מהו הסדר הנכון של שלבי מתקפת SolarWinds, כפי שתוארו בשיעור?","options":["החדרת SUNBURST ← פריצה ל-build ← הפצת העדכון ← אחיזה ברשתות הלקוחות","פריצה ל-build ← החדרת SUNBURST ← הפצת העדכון ← אחיזה ברשתות הלקוחות","פריצה ל-build ← הפצת העדכון ← החדרת SUNBURST ← אחיזה ברשתות הלקוחות","הפצת העדכון ← פריצה ל-build ← החדרת SUNBURST ← אחיזה ברשתות הלקוחות"],"correct":1,"explain":"קודם נפרצה סביבת ה-build (09.2019), אחר כך הוכנס SUNBURST לקוד העדכון, העדכון הנגוע הופץ ללקוחות ממשלתיים ופרטיים, ורק אז הקוד אוקטב ונתן לתוקפים אחיזה ברשתות. אי אפשר להחדיר קוד לפני שפורצים לשרשרת הייצור.","kind":"process","difficulty":3,"slide":"17"},
  {"q":"מתקפת SolarWinds הוצגה בשיעור כדוגמה מובהקת לאיזה סוג פגיעה?","options":["מתקפת מניעת שירות מבוזרת (DDoS) על שרתי העדכון","איום פנימי (Insider Threat)","פגיעה דרך שרשרת האספקה (Supply Chain)","פישינג ממוקד לעובדי הארגון"],"correct":2,"explain":"השקופית מציינת במפורש \"פגיעה דרך שרשרת האספקה\": התוקפים לא תקפו את הלקוחות ישירות אלא את הספק שלהם, ודרך ערוץ העדכונים המהימן שלו הגיעו לכולם.","kind":"concept","difficulty":2,"slide":"18"},
  {"q":"אילו מההשלכות של מתקפת SolarWinds הודגשו בשיעור כשינוי רוחבי בקרב ארגונים?","options":["הפסקת השימוש בעדכוני תוכנה אוטומטיים מספקים חיצוניים","מעבר מתוכנות ניטור מסחריות לפיתוח עצמי בתוך הארגון","קיצוץ בתקציבי הגנת הסייבר לטובת רכישת ביטוח סייבר","שינוי מדיניות אבטחת תוכנה ועלייה ברכש הגנות סייבר"],"correct":3,"explain":"מלבד הנזק ל-SolarWinds עצמה (ירידה חדה במניה, פגיעה במוניטין, נזקים כלכליים, רגולטוריים ומשפטיים, הודעות לרגולטורים), המרצה הדגישה שתי השלכות רוחביות: שינוי מדיניות אבטחת תוכנה בארגונים ועלייה ברכש הגנות סייבר.","kind":"case","difficulty":2,"slide":"18"},
  {"q":"\"משולש הקסם\" שממנו בנוי מרחב הסייבר כולל את המרכיבים:","options":["סודיות, שלמות וזמינות המידע","אימות זהות, הרשאות ורישום","מהירות, שליטה ועוצמה","אנשים, תהליכים וטכנולוגיה"],"correct":3,"explain":"מרחב הסייבר בנוי משלושה מרכיבים – אנשים (People), תהליכים (Process) וטכנולוגיה (Technology). שאר התשובות הן מודלים אחרים מהשיעור: CIA, AAA וטרילמת הסייבר.","kind":"concept","difficulty":1,"slide":"19"},
  {"q":"מה המסקנה המרכזית שהמרצה הדגישה לגבי שלושת מרכיבי משולש הקסם?","options":["מספיק לאבטח את הטכנולוגיה, ושאר המרכיבים יסתדרו","אם אחד מהשלושה לא מאובטח – בפועל שום דבר לא מאובטח","די לאבטח שניים מתוך השלושה כדי להגיע להגנה סבירה","כל מרכיב מאובטח בנפרד ואין תלות בין שלושת המרכיבים"],"correct":1,"explain":"\"אם אחד מהשלושה לא מאובטח, בפועל שום דבר לא מאובטח\" – האבטחה נקבעת לפי החוליה החלשה. לכן אי אפשר להסתפק בטכנולוגיה טובה בלי אנשים מודעים ונהלים מסודרים.","kind":"concept","difficulty":1,"slide":"20"},
  {"q":"לפי חלוקת משולש הקסם, איזה מהבאים שייך למרכיב \"תהליכים\" (Process)?","options":["נהלים, הוראות עבודה ותוכניות פעולה","המפתחים והאדמינים של מערכות הארגון","שרתים, רשתות ושירותי ענן","מכשירי IoT המחוברים לרשת הארגונית"],"correct":0,"explain":"תהליכים = נהלים, הוראות עבודה ותכניות פעולה. מפתחים ואדמינים שייכים ל\"אנשים\", ושרתים, רשתות, ענן ו-IoT שייכים ל\"טכנולוגיה\".","kind":"concept","difficulty":1,"slide":"20"},
  {"q":"לפי השיעור, מדוע יש להטמיע \"שגרת עדכון מתמדת\" שאינה מוגבלת לטכנולוגיה בלבד?","options":["כי מקרה SolarWinds הוכיח שאסור לסמוך על עדכוני תוכנה שמגיעים מספקים חיצוניים","כי עדכוני תוכנה הם בעצמם הגורם העיקרי לפריצות, ולכן יש לצמצם אותם למינימום","כי כל שינוי טכנולוגי משפיע גם על נהלי העבודה וגם על האנשים שמפעילים אותה","כי הטכנולוגיה כמעט אינה משתנה לאורך השנים, ולכן העדכונים נדרשים רק לאנשים"],"correct":2,"explain":"הטכנולוגיה תמיד משתנה (מעבדים, מערכות הפעלה, דפדפנים, מסגרות פיתוח, עננים, IoT), וכל שינוי משפיע גם על נהלי העבודה (איך מתפעלים ומתחזקים) וגם על האנשים שצריכים להסתגל. לכן העדכון חייב לכלול טכנולוגיה, גורם אנושי ונהלים. השיעור אינו ממליץ לצמצם עדכונים – להפך, ברכיב הטכנולוגיה נדרשים עדכונים תמידיים, אדהוקיים ומתוכננים.","kind":"process","difficulty":2,"slide":"21"},
  {"q":"בחברת ביטוח, עובדים משתמשים בסיסמה \"123456\" ומנהלת המחלקה מתעלמת מהתראות אבטחה. איזה מרכיב במשולש מרחב הסייבר מודגם כאן כחוליה החלשה?","options":["אנשים","תהליכים","טכנולוגיה","תשתיות דיגיטליות"],"correct":0,"explain":"לפי השיעור החוליה החלשה היא האנשים: טעויות אנוש, חוסר מודעות, שימוש בסיסמאות חלשות או התעלמות מנהלים – \"שער פרוץ שקל להיכנס דרכו\". הבעיה כאן היא התנהגות אנושית ולא הטכנולוגיה.","kind":"scenario","difficulty":1,"slide":"22-23"},
  {"q":"לפי המרצה, מה הופך את ה\"אנשים\" לחוליה החלשה במרחב הסייבר?","options":["מעבדים חדשים, מערכות הפעלה חדשות ומסגרות פיתוח","היעדר נהלים כתובים, מדריכים ותוכניות פעולה","תשתיות מבוזרות שהן יעד מתמיד לתקיפה","טעויות אנוש, חוסר מודעות וסיסמאות חלשות"],"correct":3,"explain":"טעויות אנוש, חוסר מודעות, סיסמאות חלשות והתעלמות מנהלים הם \"שער פרוץ\". מעבדים ומערכות הפעלה מתארים את השינוי הטכנולוגי, ונהלים כתובים הם הפתרון בצד התהליכים – לא הסיבה לחולשת האנשים.","kind":"concept","difficulty":2,"slide":"23"},
  {"q":"לפי השיעור, על אילו שאלות צריכים נהלים, מדריכים ותוכניות פעולה לענות תמיד?","options":["מי נכנס? מה מותר לו? ואיך נפקח עליו?","מהם הנכסים? מה יקרה אם יוצפנו? מי יתקוף?","מה? למה? איפה? מתי? מי? ואיך?","מה נגנב? מתי זה זוהה? וכמה זה עלה?"],"correct":2,"explain":"כדי לחזק את התהליכים כותבים נהלים, מדריכים ותוכניות פעולה שעונים תמיד על: מה? למה? איפה? מתי? מי? ואיך? \"מי נכנס / מה מותר / איך נפקח\" מתאר את AAA, ו\"נכסים / הצפנה / מי יתקוף\" הן שאלות התרגול הקבוצתי.","kind":"process","difficulty":2,"slide":"24"},
  {"q":"בבית חולים מתקינים עדכוני אבטחה רק לאחר שמתגלה תקלה, ואין ניטור שוטף של השרתים. לפי השיעור, מה ההמלצה המתאימה ביותר לרכיב הטכנולוגיה?","options":["להעביר את כל השרתים לענן ציבורי, וכך לבטל לחלוטין את הצורך בעדכונים","להוסיף עדכונים תמידיים ומתוכננים לצד האדהוקיים, וניטור ובקרה","להסתפק בהדרכת העובדים, שכן האנשים הם החוליה החלשה במשולש","לצמצם עדכונים ככל האפשר כדי לא לפגוע בזמינות המערכות"],"correct":1,"explain":"תשתיות הדיגיטל הן הבסיס – ולכן יעד מתמיד לתקיפה – וחייבות בקרה ואבטחה: עדכונים תמידיים, אדהוקיים ומתוכננים, ניטור ובקרה ועבודה לפי נהלים. הדרכת עובדים חשובה, אך אינה סוגרת את הפער בצד הטכנולוגיה.","kind":"scenario","difficulty":2,"slide":"25"},
  {"q":"לפי השיעור, מדוע תשתיות הדיגיטל הן \"יעד מתמיד לתקיפה\"?","options":["כי הן מיושנות ואינן מתעדכנות לאורך השנים","משום שהן הבסיס לטכנולוגיות של היום ושל המחר","כי הן מופעלות בידי האנשים – החוליה החלשה","כי הן אינן כפופות לנהלים ולרגולציה בארגון"],"correct":1,"explain":"בשקופית: תשתיות הדיגיטל מספקות בסיס יציב ומבוזר לטכנולוגיות של היום ושל המחר – אך בדיוק משום שהן הבסיס, הן יעד מתמיד לתקיפה, ולכן חייבות להיות תחת בקרה ואבטחה (עדכונים תמידיים, אדהוקיים ומתוכננים, ניטור ובקרה, עבודה לפי נהלים). החוליה החלשה (אנשים) היא נושא נפרד במשולש.","kind":"concept","difficulty":2,"slide":"25"},
  {"q":"מהי \"ההרחבה בעידן הנוכחי\" שהוצגה למשולש הקסם?","options":["הוספת רגולציה כמרכיב רביעי ונפרד","הוספת AI כחלק ממרכיב הטכנולוגיה במשולש","החלפת מרכיב התהליכים במודל AAA","איחוד האנשים והתהליכים לרכיב אחד"],"correct":1,"explain":"בשקופית \"משולש הקסם – הרחבה בעידן הנוכחי\" נוסף לצד הטכנולוגיה עיגול AI: הבינה המלאכותית היא חלק מהטכנולוגיה שיש לאבטח ולנהל, וגם מקור לאיומים חדשים. המשולש נשאר בן שלושה מרכיבים.","kind":"concept","difficulty":2,"slide":"26"},
  {"q":"לפי הכתבה \"AI-enabled bank fraud is a problem right now, and we are not ready\" (2025) שהוצגה בשיעור, מה מצב המגזר הפיננסי?","options":["המגזר מסתמך על שיטות מיושנות, ועבריינים חודרים בעזרת AI","הבנקים כבר מוכנים היטב, והאיום העיקרי מופנה ללקוחות הפרטיים","האיום העיקרי על הבנקים הוא DDoS על אתרי השירות ולא הונאות","הרגולציה הפיננסית הקיימת כבר נותנת מענה מלא להונאות AI"],"correct":0,"explain":"הכתבה (שלומית וגמן, Harvard Kennedy School) טוענת שתעשיית השירותים הפיננסיים נשענת על שיטות מיושנות לזיהוי ולמאבק בהונאות, ובעזרת AI עבריינים חודרים למערכות פגיעות – ולכן נדרשת פעולה משותפת. הבעיה היא \"עכשיו\", לא בעתיד.","kind":"case","difficulty":2,"slide":"27"},
  {"q":"לפי מודל CIA, מה פירוש \"זמינות\" (Availability)?","options":["מידע נגיש רק למורשים בעלי הרשאות מתאימות","מידע ומערכות נשארים שלמים, מדויקים ותקינים","מערכות ושירותים נגישים 24/7 או לפי הצורך העסקי","תיעוד ורישום של כל פעולות המשתמשים במערכת"],"correct":2,"explain":"זמינות = מערכות ושירותים זמינים 24/7 או לפי הצורך העסקי. \"נגיש רק למורשים\" היא סודיות, \"שלמים ותקינים\" היא שלמות, ותיעוד פעולות שייך ל-Accounting במודל AAA.","kind":"concept","difficulty":1,"slide":"28"},
  {"q":"עובד בבנק שולח בטעות קובץ עם פרטי לקוחות לנמען חיצוני שאינו מורשה. איזה יעד במודל CIA נפגע בעיקר?","options":["שלמות (Integrity)","זמינות (Availability)","אימות זהות (Authentication)","סודיות (Confidentiality)"],"correct":3,"explain":"סודיות פירושה שהמידע נגיש רק למורשים. כאן גורם לא מורשה קיבל גישה למידע – פגיעה בסודיות. המידע לא שונה (שלמות) והשירות לא הושבת (זמינות).","kind":"scenario","difficulty":1,"slide":"29"},
  {"q":"תוקף חדר למערכת הציונים של אוניברסיטה ושינה ציונים של סטודנטים, בלי שהדבר זוהה. איזה יעד במודל CIA נפגע?","options":["שלמות (Integrity)","סודיות (Confidentiality)","זמינות (Availability)","הרשאות (Authorization)"],"correct":0,"explain":"שלמות = המידע נשאר מדויק, שלם ולא עבר שינוי ללא הרשאה. שינוי ציונים הוא בדיוק שינוי לא מורשה של מידע. אמצעי הגנה מתאימים: חתימות דיגיטליות, Hashing ובקרת גרסאות.","kind":"scenario","difficulty":1,"slide":"30"},
  {"q":"אתר האינטרנט של בנק קרס לכמה שעות לאחר שהוצף בבקשות ממספר עצום של מחשבים. איזו התאמה בין היעד שנפגע לסוג המתקפה נכונה?","options":["שלמות – מתקפת שרשרת אספקה","סודיות – דליפת מידע","זמינות – מתקפת פישינג","זמינות – מתקפת DDoS"],"correct":3,"explain":"הצפת שרת בבקשות ממקורות רבים היא DDoS (מניעת שירות מבוזרת), והיא פוגעת בזמינות – כמו המתקפות על בנקים אמריקאיים ב-2012 שהשביתו אתרי שירות. פישינג אינו מפיל אתרים; הוא מכוון בדרך כלל לגניבת פרטים.","kind":"scenario","difficulty":2,"slide":"31"},
  {"q":"איזה צירוף אמצעים הוצג בשיעור כשיטות הגנה על סודיות (Confidentiality)?","options":["חתימות דיגיטליות, Hashing ובקרת גרסאות","שרתים עם יתירות, גיבויים ו-DRP","הצפנת קבצים, ניהול זהויות (IAM) ושימוש ב-MFA","לוגים, Audit Trails וכלי SIEM"],"correct":2,"explain":"סודיות: הצפנת קבצים, IAM ו-MFA. חתימות דיגיטליות, Hashing ובקרת גרסאות מגינים על שלמות; יתירות, גיבויים ו-DRP על זמינות; ולוגים ו-SIEM שייכים ל-Accounting.","kind":"tool","difficulty":2,"slide":"29"},
  {"q":"ארגון מחשב ערך Hash לכל קובץ חוזה ובודק מדי יום שהערך לא השתנה. על איזה יעד הוא שומר בעיקר?","options":["סודיות (Confidentiality)","שלמות (Integrity)","זמינות (Availability)","רישום ובקרה (Accounting)"],"correct":1,"explain":"Hashing הוצג כשיטת הגנה על שלמות: כל שינוי בקובץ משנה את ערך ה-Hash, ולכן אפשר לגלות שינוי לא מורשה. Hashing לבדו אינו מסתיר את התוכן (סודיות) ואינו שומר על זמינות.","kind":"tool","difficulty":2,"slide":"30"},
  {"q":"ארגון רוצה להבטיח שאם שרת מרכזי ייפול, השירות ימשיך לפעול ללא הפסקה. איזה אמצעי מתאים ביותר, ולאיזה יעד הוא שייך?","options":["Hashing – שלמות המידע והקבצים","MFA – סודיות","יתירות (Redundancy) – זמינות","SIEM – רישום ובקרה"],"correct":2,"explain":"שרתים עם יתירות (Redundancy), לצד גיבויים ו-DRP, הם שיטות ההגנה על זמינות שהוצגו בשיעור: נפילת רכיב אחד לא משביתה את השירות.","kind":"tool","difficulty":1,"slide":"31"},
  {"q":"דליפת המידע ב-Yahoo (2013–2014) הוצגה בשיעור כדוגמה לפגיעה באיזה יעד?","options":["סודיות (Confidentiality)","זמינות (Availability)","שלמות (Integrity)","הרשאות (Authorization)"],"correct":0,"explain":"Yahoo היא הדוגמה לפגיעה בסודיות: מידע אישי של מיליוני משתמשים נחשף לגורמים לא מורשים. המידע לא שונה ולא הושבת – הוא דלף.","kind":"case","difficulty":1,"slide":"29"},
  {"q":"איזה פריט מהמידע שנגנב ב-Yahoo צוין בשיעור כמידע שחלקו כלל לא היה מוצפן?","options":["הסיסמאות עצמן של המשתמשים","מספרי כרטיסי אשראי של המשתמשים","תמונות ומסמכים שהעלו המשתמשים","שאלות ותשובות לשחזור סיסמאות"],"correct":3,"explain":"לפי השקופית נגנבו שמות משתמש, כתובות מייל, טלפונים, תאריכי לידה, סיסמאות מוצפנות (hashed) ושאלות ותשובות לשחזור סיסמאות – חלקן לא מוצפנות. הסיסמאות עצמן היו hashed, וכרטיסי אשראי לא הופיעו ברשימה.","kind":"case","difficulty":3,"slide":"29"},
  {"q":"איזו התאמה בין אירוע אמיתי שהוצג בשיעור לבין יעד ה-CIA שנפגע היא הנכונה?","options":["דליפת המידע ב-Yahoo – זמינות","ניסיונות התערבות בבחירות בארה\"ב – שלמות","מתקפות DDoS על בנקים אמריקאיים (2012) – סודיות","דליפת המידע ב-Yahoo – שלמות"],"correct":1,"explain":"בשיעור: Yahoo (2013–2014) – סודיות; שינוי תוצאות הצבעה במערכות מקוונות (דוח הסנאט על תקיפת מערכות הבחירות ב-50 המדינות) – שלמות; DDoS על בנקים אמריקאיים (2012) – זמינות.","kind":"case","difficulty":2,"slide":"29-31"},
  {"q":"מהו DRP, שהוזכר בשיעור כאמצעי הגנה על זמינות?","options":["מדיניות לניהול זכויות דיגיטליות (Digital Rights Policy)","פרוטוקול לחתימה דיגיטלית על מסמכים רגישים","תוכנית התאוששות מאסון (Disaster Recovery Plan)","מנגנון להצפנת קבצים בעת שליחתם החוצה"],"correct":2,"explain":"DRP = Disaster Recovery Plan – תוכנית התאוששות מאסון שמאפשרת להחזיר את המערכות לפעולה אחרי אירוע. יחד עם יתירות וגיבויים היא שומרת על זמינות.","kind":"concept","difficulty":1,"slide":"31"},
  {"q":"מה מתאר התרשים (תוקפים ← בוט ← שרתי DNS Resolver ← קורבן) שהוצג בשקופית הזמינות?","options":["מתקפת DDoS – הצפת הקורבן בתעבורה ממקורות רבים","מתקפת שרשרת אספקה – החדרת קוד זדוני לעדכון תוכנה רשמי","פישינג – הודעה מתחזה עם קישור לאתר מזויף","הרעלת מודלים – שינוי נתוני האימון של AI"],"correct":0,"explain":"התרשים מראה תוקף שמפעיל בוטים, ואלה גורמים לשרתי DNS רבים להציף את הקורבן בתעבורה – מתקפת מניעת שירות מבוזרת (DDoS), שפוגעת בזמינות.","kind":"concept","difficulty":2,"slide":"31"},
  {"q":"מהם שלושת הרכיבים של הרחבת AAA למודל CIA?","options":["Availability, Access, Authentication","Authentication, Authorization, Accounting","Authorization, Awareness, Availability","Accountability, Anonymity, Authentication"],"correct":1,"explain":"AAA = Authentication (אימות זהות), Authorization (הרשאות), Accounting (רישום ובקרה). Availability שייכת ל-CIA ולא ל-AAA.","kind":"concept","difficulty":1,"slide":"32"},
  {"q":"מהו הסדר הלוגי של רכיבי AAA כאשר משתמש ניגש למערכת?","options":["הרשאות ← אימות זהות ← רישום ובקרה","רישום ובקרה ← אימות זהות ← הרשאות","אימות זהות ← רישום ובקרה ← הרשאות","אימות זהות ← הרשאות ← רישום ובקרה"],"correct":3,"explain":"קודם מוודאים שהמשתמש הוא מי שהוא טוען (Authentication); \"אחרי שזיהינו את המשתמש\" מחליטים מה מותר לו (Authorization); ומתעדים מה עשה (Accounting). אי אפשר לקבוע הרשאות לפני שיודעים מי המשתמש.","kind":"process","difficulty":2,"slide":"33-35"},
  {"q":"עובד מתחבר ל-VPN של הארגון ומתבקש להזין שם משתמש, סיסמה וקוד חד-פעמי (OTP) שנשלח לטלפון. איזה רכיב של AAA מתבצע כאן?","options":["Authorization – הרשאות","Authentication – אימות זהות","Accounting – רישום ובקרה של הפעולות","Availability – זמינות"],"correct":1,"explain":"זו בדיוק הדוגמה מהשיעור ל-Authentication: המערכת מוודאת שהמשתמש הוא באמת מי שהוא טוען באמצעות שם משתמש + סיסמה + OTP (MFA). ההחלטה מה מותר לו לעשות תבוא רק אחר כך (Authorization).","kind":"scenario","difficulty":1,"slide":"33"},
  {"q":"איזה מהבאים הוא דוגמה נכונה לאימות רב-שלבי (MFA)?","options":["סיסמה ארוכה ומורכבת במיוחד","שתי סיסמאות שונות שהמשתמש זוכר בעל פה","סיסמה + קוד חד-פעמי (OTP) שנשלח לטלפון","שם משתמש + סיסמה בלבד"],"correct":2,"explain":"MFA משלב גורמי אימות מסוגים שונים – משהו שאתה יודע (סיסמה) ומשהו שיש לך (טלפון שמקבל OTP), כמו בדוגמת ה-VPN בשיעור. שתי סיסמאות הן עדיין אותו סוג גורם, ולכן אינן MFA.","kind":"tool","difficulty":3,"slide":"33"},
  {"q":"במערכת המסמכים של הארגון, מנהל מערכת (Admin) יכול ליצור משתמשים חדשים, ואילו עובד רגיל יכול רק לקרוא מסמכים. איזה רכיב בא כאן לידי ביטוי?","options":["Authorization – הרשאות","Authentication – אימות זהות","Accounting – רישום ובקרה","Integrity – שלמות"],"correct":0,"explain":"Authorization: אחרי שזיהינו את המשתמש מחליטים מה מותר לו לעשות – וזו הדוגמה מהשיעור (Admin מול עובד רגיל). Authentication רק מוודא מי המשתמש ואינו קובע מה מותר לו.","kind":"scenario","difficulty":1,"slide":"34"},
  {"q":"משתמש הזין שם משתמש, סיסמה נכונה וקוד OTP ונכנס למערכת, אך כשניסה למחוק מסמך קיבל הודעה \"אין לך הרשאה לפעולה זו\". באיזה שלב של תהליך AAA הוא נחסם?","options":["Authentication – אימות זהות","Accounting – רישום ובקרה","הוא לא נחסם – זו תקלת זמינות","Authorization – הרשאות"],"correct":3,"explain":"שלב האימות (Authentication) עבר בהצלחה – המערכת זיהתה אותו. החסימה התרחשה בשלב ההחלטה מה מותר לו לעשות (Authorization), למשל לפי RBAC. ה-Accounting רק יתעד את הניסיון, הוא לא חוסם.","kind":"process","difficulty":2,"slide":"33-35"},
  {"q":"באילו שיטות מממשים Authorization (הרשאות) לפי השיעור?","options":["SIEM כמו Splunk, QRadar ו-Elastic","RBAC, ABAC וקבוצות ב-Active Directory/IAM","סיסמאות, תעודות דיגיטליות וכרטיסים חכמים","שמירת לוגים, Audit Trails וניטור שימוש במשאבים"],"correct":1,"explain":"Authorization ממומש באמצעות RBAC, ABAC וניהול קבוצות משתמשים ב-Active Directory או IAM בענן. סיסמאות, תעודות וכרטיסים חכמים הם כלי Authentication, ולוגים ו-SIEM הם כלי Accounting.","kind":"tool","difficulty":2,"slide":"34"},
  {"q":"בשיטת RBAC (Role-Based Access Control), על בסיס מה נקבעות ההרשאות?","options":["מאפיינים כמו מיקום, שעה וסוג המכשיר","קוד חד-פעמי שנשלח לטלפון של המשתמש","תפקיד המשתמש בארגון","ניתוח לוגים בזמן אמת בכלי SIEM"],"correct":2,"explain":"RBAC = בקרת גישה מבוססת תפקיד: ההרשאות נגזרות מהתפקיד (למשל Admin מול עובד רגיל). הרשאות לפי מאפיינים (מיקום, שעה, מכשיר) הן ABAC – Attribute-Based Access Control.","kind":"tool","difficulty":2,"slide":"34"},
  {"q":"לאחר אירוע אבטחה, צוות החקירה בודק מתי התחבר כל משתמש ל-VPN, מאיזו כתובת IP, לכמה זמן ומה עשה. על איזה רכיב AAA הוא נשען?","options":["Accounting – רישום ובקרה","Authentication – אימות זהות","Authorization – הרשאות","Availability – זמינות"],"correct":0,"explain":"מטרת Accounting (Auditing) היא לתעד מה המשתמש עשה כדי שנוכל לבדוק, לנתח או לחקור במקרה של תקלה/תקיפה – וזו בדיוק דוגמת תיעוד חיבורי ה-VPN מהשיעור.","kind":"scenario","difficulty":1,"slide":"35"},
  {"q":"Splunk, QRadar ו-Elastic הוזכרו בשיעור כדוגמאות לכלי:","options":["IAM","MFA","DRP","SIEM"],"correct":3,"explain":"אלה כלי SIEM לאיסוף וניתוח לוגים ואירועי אבטחה, והם שייכים לרכיב Accounting (רישום ובקרה). IAM מנהל זהויות, MFA מאמת זהות ו-DRP היא תוכנית התאוששות מאסון.","kind":"tool","difficulty":1,"slide":"35"},
  {"q":"באיזה שם נוסף מכונה רכיב ה-Accounting במודל AAA?","options":["Auditing","Availability","Authorization","Attribution"],"correct":0,"explain":"בשקופית: \"Accounting (או Auditing) – רישום ובקרה\". Availability היא יעד של CIA, ו-Authorization הוא רכיב ההרשאות.","kind":"concept","difficulty":2,"slide":"35"},
  {"q":"לפי סיכום המרצה, מה ההבדל בין מודל CIA לבין הרחבת AAA?","options":["CIA מגדיר איך מנהלים גישה בפועל; AAA מגדיר מה רוצים להשיג","CIA מיועד לתשתיות ממשלתיות; AAA מיועד לארגונים עסקיים","CIA מגדיר מה רוצים להשיג; AAA מגדיר איך מנהלים גישה בפועל","CIA הוא מודל ישן שהוחלף לחלוטין על ידי מודל AAA"],"correct":2,"explain":"CIA מגדיר מה אנחנו רוצים להשיג (סודיות, שלמות, זמינות); AAA מגדיר איך מנהלים גישה בפועל – מי נכנס, מה מותר לו לבצע ואיך נפקח עליו. יחד הם בסיס תאורטי + יישומי לכל מערכת אבטחה מודרנית.","kind":"concept","difficulty":2,"slide":"36"},
  {"q":"לפי סיכום השיעור, מה עלול לקרות אם אחד ממרכיבי CIA + AAA נפגע?","options":["רק המרכיב שנפגע מושבת, והשאר ממשיכים לפעול כרגיל","שאר המרכיבים מפצים עליו, ולכן הנזק נשאר מקומי","נפגעת רק הסודיות, כי AAA ממשיך להגן על השאר","המערכת כולה עלולה לקרוס, ולא רק המרכיב שנפגע"],"correct":3,"explain":"הסיכום בשקופית: מודל CIA + הרחבות AAA הוא הבסיס להבנת כל מערך אבטחת מידע, ואם אחד מהמרכיבים נפגע – המערכת כולה עלולה לקרוס. המרכיבים תלויים זה בזה ואינם \"מפצים\" זה על זה, ולכן הנזק לא נשאר מקומי – אותו היגיון של \"החוליה החלשה\" במשולש הקסם.","kind":"concept","difficulty":1,"slide":"36"},
  {"q":"כיצד תיארה המרצה את התפתחות תחום אבטחת המידע?","options":["מאתגר ניהולי ורגולטורי לבעיה טכנית נקודתית של אנשי IT","מניהול בעיות טכניות נקודתיות לאתגר ניהולי, רגולטורי וגיאו-פוליטי","מתחום צבאי וביטחוני סגור לתחום אזרחי שעוסק כמעט רק בפרטיות המשתמשים","מנושא של הנהלה ודירקטוריון לנושא טכני של צוות התשתיות"],"correct":1,"explain":"התחום התפתח מניהול בעיות טכניות נקודתיות לאתגר ניהולי, רגולטורי וגיאו-פוליטי. היום סייבר אינו רק עניין של אנשי IT אלא נושא לדיוני הנהלה, דירקטוריון וממשלות – הכיוון ההפוך הוא המלכודת.","kind":"concept","difficulty":1,"slide":"37"},
  {"q":"לפי הכתבה שהוצגה בשיעור, מה מחייב תיקון 13 לחוק הגנת הפרטיות?","options":["מינוי דירקטור סייבר חיצוני בכל חברה","מינוי ממונה פרטיות","דיווח שנתי לרשות הסייבר הלאומית","הצפנה של כל מאגרי המידע בענן"],"correct":1,"explain":"לפי הכתבה (\"תיקון 13: חוקי הפרטיות בישראל מתיישרים עם העולם\"), התיקון מחייב מינוי ממונה פרטיות ומבשר על שינוי משמעותי בגישת ישראל לפרטיות – דוגמה לכך שסייבר ופרטיות הפכו לאתגר רגולטורי.","kind":"fact","difficulty":2,"slide":"40"},
  {"q":"בשיעור הוצגה הנחיית רשות הגנת הפרטיות מס' 1/2024 (ספטמבר 2024). במה היא עוסקת?","options":["חובת מינוי ממונה פרטיות בארגונים","הגדרת ארגונים חיוניים לצורך הגנת סייבר לאומית","חובת דיווח מיידי לרשות על כל מתקפת DDoS","תפקיד הדירקטוריון בהגנת הפרטיות ובאבטחת מידע"],"correct":3,"explain":"הנחיה 1/2024 (3.9.2024) – \"הגנת הפרטיות ואבטחת מידע – תפקיד הדירקטוריון\": מטרתה לקבוע ולהגדיר את החובות והפעולות של דירקטוריון החברה כדי לעמוד בדרישות הדין, ובתי המשפט מעניקים תוקף להנחיות הרשות. מינוי ממונה פרטיות שייך לתיקון 13, וארגונים חיוניים – להצעת חוק הגנת הסייבר הלאומית.","kind":"fact","difficulty":2,"slide":"40"},
  {"q":"לפי דברי ההסבר להצעת חוק הגנת הסייבר הלאומית (התשפ\"ו–2026) שהוצגו בשיעור, מדוע נדרשת חקיקה?","options":["כי רוב התקיפות על ישראל מגיעות מגורמים פנימיים בתוך הארגונים","כי תקיפות הסייבר מכוונות כמעט רק לגופים ממשלתיים ולא לאזרחיים","כי הגורמים המקצועיים מעריכים שהיקף תקיפות הסייבר לא יפחת","כי התקיפות מאז 2023 הן בעיקר מחאה של האקטיביסטים ללא נזק ממשי"],"correct":2,"explain":"דברי ההסבר: ישראל היא מהמדינות המותקפות ביותר בעולם; מאז 7 באוקטובר 2023 ניכרה עלייה משמעותית בהיקף ובעוצמה של תקיפות נגד גופים אזרחיים במשק (לא רק ממשלתיים), כחלק ממתקפה משולבת נגד חוסן המדינה – וההערכה היא שהיקפן לא יפחת. לכן נדרשת חקיקה שתבטיח הגנה על הארגונים, ודרכם על המשק, החוסן הלאומי וביטחון המדינה.","kind":"fact","difficulty":2,"slide":"41, 48"},
  {"q":"לפי הטקסט על התקיפות נגד ישראל שהוצג בשיעור, מדוע ארגונים חיוניים (אנרגיה, בריאות, תחבורה, תקשורת) מודגשים במיוחד?","options":["כי הפגיעה בהם חורגת מהארגון הבודד ועלולה לפגוע בציבור ובמשק","כי הם הגופים היחידים במשק שמחזיקים מידע אישי ורפואי של אזרחים","כי הם פטורים כיום מכל רגולציה בתחום הסייבר והפרטיות","כי הם מותקפים בעיקר על ידי האקטיביסטים ולא על ידי מדינות"],"correct":0,"explain":"פוטנציאל הפגיעה בארגונים חיוניים, מעצם מהותם, חורג מהנזק לארגון הבודד ועלול להביא לפגיעה רחבה בציבור או במשק – ואף בחיי אדם, בשגרה ובחירום. לכן הם במוקד הצעת חוק הגנת הסייבר הלאומית.","kind":"case","difficulty":2,"slide":"48"},
  {"q":"בתרגול הקבוצתי, כל קבוצה קיבלה ארגון (בנק, בית חולים, מקורות, תחנת כח ועוד). אילו שאלות היה עליה להגדיר?","options":["מה? למה? איפה? מתי? מי? ואיך?","מי נכנס למערכת? מה מותר לו לבצע? ואיך נפקח עליו בפועל?","מהו התקציב? מי הספקים? ואילו מערכות ענן ישמשו את הארגון?","מהם הנכסים הקריטיים? מה יקרה אם יוצפנו? מי ירצה לתקוף?"],"correct":3,"explain":"שאלות התרגול: מה הם הנכסים הקריטיים? מה יקרה אם יוצפנו? מי ירצה לתקוף אותם? – ניתוח סיכונים בסיסי: מה מגינים, מה ההשפעה ומי האיום. \"מה/למה/איפה/מתי/מי/איך\" הן שאלות לכתיבת נהלים.","kind":"process","difficulty":2,"slide":"39"},
  {"q":"בניתוח הסיכונים מהתרגול הקבוצתי, מה השלב הראשון – לפני שבודקים \"מה יקרה אם יוצפנו?\" ו\"מי ירצה לתקוף?\"","options":["לזהות מה הם הנכסים הקריטיים של הארגון","לזהות את התוקף הסביר ואת המניע שלו","להעריך את הנזק שייגרם אם המערכות יוצפנו","לכתוב נוהל שעונה על מה, למה, איפה, מתי, מי ואיך"],"correct":0,"explain":"סדר השאלות בתרגול: קודם מזהים מה הם הנכסים הקריטיים (מה מגינים), אחר כך מה יקרה אם יוצפנו (ההשפעה), ולבסוף מי ירצה לתקוף אותם (האיום). בלי לדעת מה הנכסים אי אפשר להעריך נזק או תוקף.","kind":"process","difficulty":2,"slide":"39"},
  {"q":"בתרגול הקבוצתי, השאלה \"מי ירצה לתקוף אותם?\" נשענת בעיקר על איזה חלק מהשיעור?","options":["זירת האיומים – סוג התוקף לפי מניע ויעד","מודל CIA – סודיות, שלמות וזמינות","משולש הקסם – אנשים, תהליכים וטכנולוגיה","הרחבת AAA – אימות, הרשאות ורישום"],"correct":0,"explain":"כדי לענות על \"מי ירצה לתקוף?\" מזהים את התוקף הסביר בזירת האיומים: פושעי סייבר (כסף), האקטיביסטים (אידיאולוגיה), מדינות (מודיעין והשפעה) או גורם פנימי (נקמה/טעות/מצוקה). מודל CIA עוזר להבין מה ייפגע (למשל זמינות אם המערכות יוצפנו), לא מי התוקף.","kind":"process","difficulty":2,"slide":"39, 44"},
  {"q":"קבוצה בתרגול קיבלה \"תחנת כח\" ועונה על השאלה \"מה יקרה אם יוצפנו?\". אם מערכות התפעול יוצפנו בידי תוקף ולא יהיה ניתן להשתמש בהן, איזה יעד במודל CIA ייפגע באופן הישיר ביותר?","options":["סודיות (Confidentiality)","שלמות (Integrity)","הרשאות (Authorization)","זמינות (Availability)"],"correct":3,"explain":"הצפנה בידי תוקף משביתה את השימוש במערכות – המידע והשירותים אינם זמינים. לכן הפגיעה הישירה היא בזמינות, ובתשתית כמו תחנת כח ההשלכות חורגות מהארגון עצמו ופוגעות בציבור.","kind":"scenario","difficulty":3,"slide":"39"},
  {"q":"לפי טבלת זירת האיומים, מהו המניע של פושעי סייבר?","options":["אידיאולוגיה","מודיעין והשפעה","כסף","נקמה, טעות או מצוקה"],"correct":2,"explain":"פושעי סייבר – מניע: כסף; יעד: ארגונים ואנשים. אידיאולוגיה היא מניע האקטיביסטים, מודיעין והשפעה – של מדינות, ונקמה/טעות/מצוקה – של גורם פנימי.","kind":"concept","difficulty":1,"slide":"44"},
  {"q":"לפי טבלת זירת האיומים, מהו היעד של גורם פנימי (Insider)?","options":["ארגונים ואנשים","הארגון עצמו","ממשלות וארגונים","תשתיות, ממשלות וארגונים"],"correct":1,"explain":"גורם פנימי פוגע בארגון שבו הוא נמצא – \"הארגון עצמו\". ארגונים ואנשים הם יעד פושעי הסייבר, ממשלות וארגונים – של האקטיביסטים, ותשתיות, ממשלות וארגונים – של מדינות.","kind":"concept","difficulty":2,"slide":"44"},
  {"q":"רשת מזון גדולה מגלה שמערכות הקופה והמלאי שלה הוצפנו, והתוקפים דורשים תשלום בביטקוין תמורת שחרורן. לפי זירת האיומים, מי התוקף הסביר ומה מניעו?","options":["האקטיביסטים – אידיאולוגיה","מדינות – מודיעין והשפעה","גורם פנימי – נקמה","פושעי סייבר – כסף"],"correct":3,"explain":"דרישת תשלום היא סימן מובהק למניע כספי – פושעי סייבר, שיעדם ארגונים ואנשים. אצל האקטיביסטים \"המטרה איננה כסף\", ומדינות פועלות לשם מודיעין, השפעה ופגיעה בתשתיות.","kind":"scenario","difficulty":1,"slide":"44-45"},
  {"q":"מדוע המרצה מתארת את פשיעת הסייבר כ\"תעשייה\"?","options":["כי הם פועלים מתוך הארגון ומכירים היטב את מערכותיו ואת נקודות התורפה","כי הם פועלים כמו סטארטאפ: שירות לקוחות, מוקדי תמיכה ותוכניות שותפים","כי הם ממומנים ומנוהלים ישירות על ידי ממשלות ושירותי מודיעין","כי הם פועלים ממניעים אידיאולוגיים ופוליטיים, ולכן מתארגנים בקבוצות גדולות"],"correct":1,"explain":"הפשיעה הקיברנטית הפכה לתעשייה: הם כמו חברות סטארטאפ עם \"שירות\" לקוחות, מוקדי תמיכה, מחלקה פיננסית, תוכניות שותפים, עמלות ותשלומי בונוסים. פעולה מתוך הארגון מאפיינת גורם פנימי, מימון ממשלתי מאפיין מדינות, ואידיאולוגיה – האקטיביסטים.","kind":"concept","difficulty":2,"slide":"45"},
  {"q":"קבוצת פעילים פורצת לאתר של משרד ממשלתי ומציבה בעמוד הבית מסר מחאה פוליטי כדי לבייש את המשרד, בלי לדרוש כסף. לאיזה סוג תוקף זה מתאים ביותר?","options":["פושעי סייבר (Cyber Crime)","גורם פנימי (Insider Threat)","האקטיביסטים (Hacktivists)","מדינות (Nation States)"],"correct":2,"explain":"האקטיביסטים: המניע הוא אג'נדה – המטרה איננה כסף; מטרות לדוגמה: מחאה, השפעה, פרסום ומבוכה ציבורית; היעד: ממשלות וארגונים. היעדר דרישה כספית מוציא את פושעי הסייבר.","kind":"scenario","difficulty":1,"slide":"46"},
  {"q":"איזה צירוף מניעים מתאים למדינות (Nation States) לפי השיעור?","options":["ריגול, מודיעין ופגיעה בתשתיות","כסף, עמלות, שותפים ותשלומי בונוסים","מחאה, פרסום ומבוכה ציבורית","עובד ממורמר, רשלנות וסחיטה"],"correct":0,"explain":"מניעי מדינות: זירת מלחמה, ריגול, מודיעין, השפעה ופגיעה בתשתיות. כסף ובונוסים – פושעי סייבר; מחאה ומבוכה – האקטיביסטים; עובד ממורמר, רשלנות וסחיטה – גורם פנימי.","kind":"concept","difficulty":2,"slide":"47"},
  {"q":"גורם בעל משאבים רבים חודר לרשתות של משרדי ממשלה במדינה יריבה ושוהה בהן חודשים בשקט כדי לאסוף מידע מסווג. לאיזה סוג תוקף זה מתאים ביותר?","options":["האקטיביסטים (Hacktivists)","פושעי סייבר (Cyber Crime)","מדינות (Nation States)","גורם פנימי (Insider Threat)"],"correct":2,"explain":"ריגול ואיסוף מודיעין לאורך זמן נגד ממשלה זרה הם מניעים מובהקים של מדינות. האקטיביסטים מחפשים פרסום ומבוכה ציבורית (ההפך מ\"שקט\"), ופושעי סייבר מחפשים כסף.","kind":"scenario","difficulty":2,"slide":"47"},
  {"q":"עובד שפוטר ממפעל שבבים מוחק, ביום עבודתו האחרון, קבצי תכנון חיוניים מתוך נקמה. מהו סוג האיום?","options":["פושעי סייבר (Cyber Crime)","גורם פנימי (Insider Threat)","האקטיביסטים (Hacktivists)","מתקפת שרשרת אספקה (Supply Chain)"],"correct":1,"explain":"גורם פנימי – בעל גישה לגיטימית לארגון – הפועל ממניע של \"עובד ממורמר\"/נקמה, ויעדו הוא הארגון עצמו. זו לא פשיעה כספית וגם לא אג'נדה ציבורית.","kind":"scenario","difficulty":1,"slide":"49"},
  {"q":"לפי השיעור, האם עובד שגרם לדליפת מידע מתוך רשלנות או טעות אנוש, ללא כוונה רעה, נחשב \"גורם פנימי\" (Insider Threat)?","options":["לא – גורם פנימי הוא רק עובד שפועל בזדון ובכוונה","לא – אירוע כזה מסווג כפשיעת סייבר ולא כגורם פנימי","רק אם העובד קיבל תשלום מגורם חיצוני על הדליפה","כן – רשלנות וטעות אנוש מופיעות בין מניעי הגורם הפנימי"],"correct":3,"explain":"בשקופית \"גורם פנימי\" מופיעים: עובד ממורמר, רשלנות, טעות אנוש, סחיטה ומצוקה כלכלית. כלומר האיום הפנימי כולל גם מקרים לא זדוניים – המלכודת היא לחשוב שמדובר רק בעובד זדוני.","kind":"concept","difficulty":2,"slide":"49"},
  {"q":"איזו מהיכולות הבאות לא הוצגה בשיעור כדרך שבה AI משרת את התוקפים?","options":["ניהול הרשאות לפי תפקיד (RBAC)","כתיבת קוד תקיפה","הרעלת מודלים","איתור חולשות הגנה מהר יותר מבעבר"],"correct":0,"explain":"לפי השיעור, באמצעות AI ניתן לייצר מיילי פישינג מושלמים, לתרגם לכל שפה, ליצור Deepfake, לכתוב קוד תקיפה, לאתר חולשות הגנה מהר יותר, להרעיל מודלים ולבצע תקיפות DDoS. RBAC הוא מנגנון הגנה (Authorization), לא יכולת תקיפה.","kind":"concept","difficulty":1,"slide":"50"},
  {"q":"תוקף מחדיר נתונים מטעים למאגר האימון של מודל AI לזיהוי הונאות, כדי שהמודל יפספס עסקאות חשודות. איזו יכולת תקיפה מהשיעור מתוארת?","options":["יצירת Deepfake","פישינג מושלם","מתקפת DDoS","הרעלת מודלים"],"correct":3,"explain":"הרעלת מודלים (Model Poisoning) – פגיעה בנתונים או באימון של מודל כך שיקבל החלטות שגויות. Deepfake מזייף תוכן, פישינג מתחזה בהודעה, ו-DDoS מציף שירות כדי להשביתו.","kind":"scenario","difficulty":2,"slide":"50"},
  {"q":"מנהלת הכספים מקבלת שיחת וידאו שבה \"המנכ\"ל\" – בפניו ובקולו – מורה לה להעביר כסף בדחיפות. בדיעבד התברר שהשיחה זויפה באמצעות AI. מה שם הטכניקה?","options":["Deepfake","הרעלת מודלים","DDoS","מתקפת שרשרת אספקה"],"correct":0,"explain":"Deepfake – זיוף פנים וקול באמצעות AI – הוא אחת היכולות שהוצגו בשקופית \"האיום החדש – AI משנה את כללי המשחק\". הרעלת מודלים פוגעת במודל עצמו ולא מזייפת אדם.","kind":"scenario","difficulty":1,"slide":"50"},
  {"q":"עובדי חברת ביטוח ישראלית מקבלים מיילים בעברית רהוטה וללא שגיאות, שנשלחו מקבוצת תוקפים בחו\"ל שאינה דוברת עברית. איזו יכולת של AI, מאלה שהוצגו בשיעור, מתוארת כאן?","options":["הרעלת מודלים של סינון הדואר בארגון","איתור חולשות הגנה מהר יותר מבעבר","תרגום לכל שפה ופישינג מושלם","יצירת Deepfake של קול ופנים"],"correct":2,"explain":"בשקופית \"האיום החדש – AI משנה את כללי המשחק\": באמצעות AI ניתן לייצר מיילי פישינג מושלמים ולתרגם לכל שפה – ולכן מחסום השפה כבר אינו מגן. הרעלת מודלים פוגעת במודל עצמו, איתור חולשות אינו קשור לניסוח ההודעה, ו-Deepfake מזייף קול ותמונה.","kind":"scenario","difficulty":1,"slide":"50"},
  {"q":"התקבלה הודעת SMS: \"מצטערים, לא ניתן היה לשלוח את החבילה, הכתובת שגויה. אנא עדכן את הכתובת כדי למנוע החזרות: israeliiposet.com\". מהו הסימן המחשיד המרכזי?","options":["ההודעה נשלחה בשעות אחר הצהריים ולא בשעות הבוקר","הקישור לדומיין שמחקה את שם הדואר בשגיאת כתיב","ההודעה כתובה בעברית ולא באנגלית","ההודעה אינה מציינת סכום כסף לתשלום"],"correct":1,"explain":"זו דוגמת הפישינג מהשיעור: התחזות לגוף מוכר (הדואר), תואנה תמימה (חבילה), לחץ (\"למנוע החזרות\") וקישור לדומיין שמחקה את השם המקורי בשגיאת כתיב (israeliiposet.com). שעת השליחה, השפה או היעדר סכום לתשלום אינם סימני פישינג. ומכיוון ש-AI מאפשר לנסח הודעות מושלמות בכל שפה, יש לבדוק את הקישור ואת השולח ולא לסמוך על שפה תקינה.","kind":"case","difficulty":2,"slide":"51"},
  {"q":"מייל עם הלוגו של \"כביש 6\" מודיע על חשבון שלא שולם, מאיים בקנסות ובאכיפה ומציע \"לחץ כאן לצפייה ולטיפול בחשבונך\". מה סוג המתקפה ומה הטכניקה המרכזית בה?","options":["DDoS – הצפת תיבת הדואר בהודעות עד להשבתתה","Deepfake – זיוף וידאו של נציג שירות הלקוחות","פישינג – התחזות לגוף מוכר ויצירת לחץ ודחיפות","הרעלת מודלים – שינוי נתוני האימון של מסנן הספאם"],"correct":2,"explain":"דוגמת \"כביש 6\" מהשיעור היא פישינג: לוגו אמיתי, איום בקנסות ובאכיפה וכפתור שמוביל לאתר התוקף. ה-AI מאפשר לייצר מיילים כאלה מושלמים ומשכנעים.","kind":"scenario","difficulty":1,"slide":"52"},
  {"q":"מהם שלושת הקודקודים של \"טרילמת הסייבר\" שהוצגה בשיעור?","options":["סודיות, שלמות וזמינות","אנשים, תהליכים וטכנולוגיה","מהירות, שליטה ועוצמה","אימות, הרשאות ורישום"],"correct":2,"explain":"טרילמת הסייבר (בחלק \"האיום החדש – AI משנה את כללי המשחק\"): מהירות, שליטה ועוצמה. אל תתבלבלו עם CIA (סודיות-שלמות-זמינות), משולש הקסם (אנשים-תהליכים-טכנולוגיה) ו-AAA.","kind":"concept","difficulty":1,"slide":"53"},
  {"q":"מה המשמעות של המונח \"טרילמה\" בטרילמת הסייבר (מהירות, שליטה, עוצמה), שהוצגה כ\"משולש בלתי אפשרי\"?","options":["שלושה שלבים עוקבים של מתקפת סייבר שיש לבצע לפי סדר קבוע מראש","קשה להשיג במלואם את שלושת הגורמים יחד, ולכן יש לאזן ביניהם","שלושה יעדים שמושגים אוטומטית כאשר מטמיעים AI בארגון","שלוש שכבות הגנה שמחליפות לחלוטין את מודל CIA"],"correct":1,"explain":"טרילמה היא מצב של שלושה יעדים מתחרים שאי אפשר למקסם את כולם בבת אחת – והשרטוט בשקופית הוא \"משולש בלתי אפשרי\". למשל, ככל שמאיצים ומעצימים באמצעות AI, קשה יותר לשמור על שליטה.","kind":"concept","difficulty":3,"slide":"53"}
]
